WITH filtered AS (SELECT id, plan, start_date, status, DATE_TRUNC('month', start_date) AS start_date_period FROM subscriptions WHERE start_date > DATE '2023-04-17' AND customer_id IS NOT NULL), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY start_date DESC, id ASC) AS dedup_rank FROM filtered QUALIFY dedup_rank = 1), prev_events AS (SELECT *, LAG(start_date_period) OVER (PARTITION BY status ORDER BY start_date_period ASC, id ASC) AS prev_start_date_period FROM deduped), with_gaps AS (SELECT *, CASE WHEN prev_start_date_period IS NULL OR start_date_period > prev_start_date_period + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM prev_events), islands AS (SELECT id, start_date, status, start_date_period, SUM(is_new_burst) OVER (PARTITION BY status ORDER BY start_date_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps), scored AS (SELECT *, SUM(session_id) OVER (PARTITION BY status ORDER BY start_date_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_session_id, RANK() OVER (PARTITION BY status ORDER BY session_id DESC) AS session_id_rank FROM islands), deduped_subscriptions AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY session_id_rank DESC, id ASC) AS latest_rank FROM scored) ranked WHERE latest_rank = 1), deduped_subscriptions_2 AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY session_id_rank DESC NULLS LAST, id ASC) AS rn FROM deduped_subscriptions QUALIFY rn = 1) SELECT CASE WHEN session_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS session_id_tier, SIZE(COLLECT_SET(status)) AS num_status, COUNT(*) FILTER (WHERE status = 'ACTIVE') AS active_rows, MIN(start_date_period) AS first_seen, PERCENTILE_APPROX(session_id_rank, ARRAY(0.25, 0.5, 0.75)) AS session_id_rank_quartiles, COUNT(*) FILTER (WHERE status = 'PAUSED') AS paused_rows, SORT_ARRAY(COLLECT_SET(status)) AS status_list FROM deduped_subscriptions_2 GROUP BY 1 HAVING paused_rows > 1 ORDER BY paused_rows ASC
